{
  "гриб": "Amanita muscaria (красный мухомор)",
  "состав": [
    {
      "вещество": "Мусцимол (4-гидроксиизовалериновый лактам)",
      "содержание": "0,5–1,7 % от сухого веса",
      "влияние": "Основной психоактивный компонент: агонист ГАМК-А-рецепторов, вызывает седацию, дизартрию и спутанность сознания."
    },
    {
      "вещество": "Иботеновая кислота (4,5-метилендиоксипиридинон)",
      "содержание": "0,5–1,5 % от сухого веса",
      "влияние": "Агонист NMDA-рецепторов, токсична для ЦНС; при нагревании дегидратируется в мусцимол."
    },
    {
      "вещество": "Хорденин (N-метил-N-винил-3,4-диоксифенилэтиламин)",
      "содержание": "1–3 мг/г сухого веса",
      "влияние": "Бета-адренергический симпатомиметик; в умеренных дозах повышает ЧСС и артериальное давление."
    },
    {
      "вещество": "Мускарин",
      "содержание": "следы, <0,01 % от сухого веса (несколько мг/кг)",
      "влияние": "Агонист мускариновых холинорецепторов; в типичных дозах мухомора клинически незначим, но при высокой концентрации усиливает парасимпатические эффекты (миоз, брадикардия)."
    },
    {
      "вещество": "Мусциновая кислота (fly agaric acid, кинон)",
      "содержание": "0,1–0,5 % от сухого веса шляпки",
      "влияние": "Красный пигмент шляпки; токсичен для насекомых, у человека обусловливает жжение и горечь при контакте со слизистыми."
    },
    {
      "вещество": "Агариковая кислота (agaricin, жёлтый кинон)",
      "содержание": "следы – до 0,1 % от сухого веса",
      "влияние": "Вторичный пигмент; придаёт жёлто-оранжевые пятна на белом мякише, слабо окрашивающее действие."
    },
    {
      "вещество": "Ланостановые тритерпены (аманит-8,24(28)-диен, амарантовая кислота и др.)",
      "содержание": "0,5–2 % от сухого веса (суммарно)",
      "влияние": "Обеспечивают горечь вкуса; в больших количествах вызывают лёгкую желчегонную и слабую антикоагулянтную активность."
    },
    {
      "вещество": "Стероидные сапонины (на основе тритерпенов)",
      "содержание": "до 1 % от сухого веса",
      "влияние": "Обладают слабой гемолитической активностью и усиливают горький привкус, при пероральном приёме могут раздражать ЖКТ."
    }
  ]
}

{
  "гриб": "Amanita pantherina (пантерный мухомор)",
  "состав": [
    {
      "вещество": "Иботиновая кислота (ibotenic acid)",
      "содержание": "2–6 мг/г сухого веса",
      "влияние": "Эксайтотоксический глутамат-агонист, вызывает судороги, тремор и возбуждение ЦНС."
    },
    {
      "вещество": "Мусцимол (muscimol)",
      "содержание": "1,5–5,5 мг/г сухого веса",
      "влияние": "Агонист GABA-A рецепторов, оказывает седативное, сноходное и антиконвульсантное действие."
    },
    {
      "вещество": "Пантерин (panterin)",
      "содержание": "0,5–2 мг/г сухого веса",
      "влияние": "Сесквитерпеновый спирт, характерен для вида; вносит вклад в нейротоксичность и горький привкус."
    },
    {
      "вещество": "Мусцин (muscine)",
      "содержание": "<1 мг/г сухого веса (следы)",
      "влияние": "Циклическая аминокислота, структурный аналог мусцимола; слабое GABA-модулирующее действие."
    },
    {
      "вещество": "Аманулин (amanulin)",
      "содержание": "≈10–15 % сухого веса (белок)",
      "влияние": "Кислотный белок Amanita, участвует в антибактериальной защите гриба; при пероральном приёме в больших дозах может давать лёгкую胃肠ную реакцию."
    },
    {
      "вещество": "Аманин (amanitin, следовые количества)",
      "содержание": "неизвестно (значительно ниже, чем в A. phalloides)",
      "влияние": "Ингибитор РНК-полимеразы II; в малых дозах в A. pantherina клинически незначим."
    }
  ]
}

{
  "гриб": "Amanita phalloides (бледная поганка)",
  "состав": [
    {
      "вещество": "α-Аманидин (α-Amanitin)",
      "содержание": "0,3–0,5 % от сухого веса",
      "влияние": "Реверсивно ингибирует РНК-полимеразу II, останавливая транскрипцию и вызывая гибель гепатоцитов."
    },
    {
      "вещество": "β-Аманидин (β-Amanitin)",
      "содержание": "0,1–0,2 % от сухого веса",
      "влияние": "Ингибирует РНК-полимеразу II, вызывая гепатоцеллюлярный некроз."
    },
    {
      "вещество": "γ-Аманидин (γ-Amanitin)",
      "содержание": "0,05–0,1 % от сухого веса",
      "влияние": "Ингибирует РНК-полимеразу II, но значительно слабее α- и β-аманидинов."
    },
    {
      "вещество": "ε-Аманидин (ε-Amanitin)",
      "содержание": "≈0,01 % от сухого веса",
      "влияние": "Слабо ингибирует РНК-полимеразу II, мало концентрируется в ткани печени."
    },
    {
      "вещество": "α-Фаллоидин (α-Phalloidin)",
      "содержание": "0,1–0,2 % от сухого веса",
      "влияние": "Диссоциирует филаментозный актин, разрушая цитоскелет гепатоцитов и нефроцитов."
    },
    {
      "вещество": "β-Фаллоидин (β-Phalloidin)",
      "содержание": "≈0,05 % от сухого веса",
      "влияние": "Связывает и диссоциирует актин-филаменты, вызывая цитолиз клеток печени и почек."
    },
    {
      "вещество": "Вирезин (Viresin)",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Принудительно диссоциирует актин-филаменты, вызывая осмотический набухание и лизис клеток."
    },
    {
      "вещество": "β-Аманиотоксин (β-Amanitoxin)",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Слабее β-аманидина ингибирует РНК-полимеразу II."
    },
    {
      "вещество": "γ-Аманиотоксин (γ-Amanitoxin)",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Слабее γ-аманидина ингибирует РНК-полимеразу II."
    }
  ]
}
